import{_ as a,o,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"篇957｜反掠夺天道规则·规则二十三——剧情不得绑架设定","description":"","frontmatter":{"title":"篇957｜反掠夺天道规则·规则二十三——剧情不得绑架设定","no":957,"module":5,"tags":["天道规则","规则二十三","剧情绑架","设定自主","法则优先公理"],"related":["0020-锚点结构与层级","956-设定自洽高于剧情便利","955-永不吃书永不烂尾"]},"headers":[],"relativePath":"zh/0957_模块5-规则二十三-剧情不得绑架设定.md","filePath":"zh/0957_模块5-规则二十三-剧情不得绑架设定.md"}'),r={name:"zh/0957_模块5-规则二十三-剧情不得绑架设定.md"};function i(u,t,n,q,h,s){return o(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="篇957-反掠夺天道规则·规则二十三——剧情不得绑架设定" tabindex="-1">篇957｜反掠夺天道规则·规则二十三——剧情不得绑架设定 <a class="header-anchor" href="#篇957-反掠夺天道规则·规则二十三——剧情不得绑架设定" aria-label="Permalink to &quot;篇957｜反掠夺天道规则·规则二十三——剧情不得绑架设定&quot;">​</a></h1><blockquote><p>所属模块：模块五·文明终极定型典藏篇｜对标地基：文档20｜系列：反掠夺天道规则大全</p></blockquote><h2 id="引言-故事是设定长出来的-不是设定被故事拖着走" tabindex="-1">引言：故事是设定长出来的，不是设定被故事拖着走 <a class="header-anchor" href="#引言-故事是设定长出来的-不是设定被故事拖着走" aria-label="Permalink to &quot;引言：故事是设定长出来的，不是设定被故事拖着走&quot;">​</a></h2><p>规则二十二讲&quot;自洽优先&quot;，规则二十三讲得更狠——连&quot;剧情&quot;这个东西本身都不得绑架设定。旧宇宙的常见堕落是：作者为了让某段冲突更激烈，回头去改设定；为了让主角更惨，回头去加旧伤；为了让结局更催泪，回头去改人物关系。设定从&quot;地基&quot;沦为&quot;剧情的提线木偶&quot;。天道规则二十三宣布：设定是自主的，剧情必须服从设定生长，而非反过来。想改剧情？先问设定答不答应。</p><p>六大顶层公理在此钉死方向：法则优先公理是本规则的本体，直接写明&quot;剧情不得绑架设定&quot;；反掠夺主义公理否定&quot;为捧主角而绑架整个世界观&quot;；万族共和公理决定设定属于万族，不是某段剧情的私产；集体升维公理要求剧情沿升维方向自然展开；因果自律公理要求剧情的每一步都走在因果实线上；公理六·众生全员无限均等法则则让&quot;绑架&quot;失去动机——既然人人自带基础无限之力，就不必为了抬高某主角而把全世界的设定往他身上拧。</p><h2 id="一、规则内容-剧情服从设定的三条" tabindex="-1">一、规则内容：剧情服从设定的三条 <a class="header-anchor" href="#一、规则内容-剧情服从设定的三条" aria-label="Permalink to &quot;一、规则内容：剧情服从设定的三条&quot;">​</a></h2><ol><li><strong>设定先于剧情</strong>：先有法则锚定，才有情节发生；剧情不得反向要求设定让步</li><li><strong>人物自主</strong>：角色的反应、选择、成长必须符合其既有性格与境界，不为催泪、为爽点而扭曲</li><li><strong>冲突来自设定本身</strong>：矛盾、张力应从设定内部自然生长（如&quot;佛系者的保底无限&quot;与&quot;卷王的叠加无限&quot;如何共存），而非外部硬塞</li></ol><h2 id="二、法理依据" tabindex="-1">二、法理依据 <a class="header-anchor" href="#二、法理依据" aria-label="Permalink to &quot;二、法理依据&quot;">​</a></h2><ul><li><strong>生长论证</strong>：《自生自长进化法则》指出，健康的因果树从种子长出来；剧情绑架设定等于把树掰成想要的形状，终将折断</li><li><strong>主角唯一性依赖论证</strong>：前锚点时代作品的通病是主角唯一性依赖度过高——主角一停，世界观就崩；衡元宙靠网络式设定，主角只是节点之一，剧情不必绑架设定</li><li><strong>无限本源论证</strong>：公理六让剧情的动力源从&quot;主角光环&quot;换成&quot;无限叠加的多样性&quot;，设定本身就足够有戏</li></ul><h2 id="三、执行机制" tabindex="-1">三、执行机制 <a class="header-anchor" href="#三、执行机制" aria-label="Permalink to &quot;三、执行机制&quot;">​</a></h2><ul><li>阿赖耶网络为每段重大叙事做&quot;设定依赖审计&quot;：这段剧情是否反向修改了既有设定</li><li>发现绑架，即冻结该段剧情的&quot;正史资格&quot;，退回求索域模拟层</li><li>设&quot;人物自主保护&quot;：角色的重大选择须经其自身因果画像校验，不被剧情强制</li><li>术语委员会、锚点校准定期审查设定是否被剧情侵蚀</li></ul><h2 id="四、违反后果" tabindex="-1">四、违反后果 <a class="header-anchor" href="#四、违反后果" aria-label="Permalink to &quot;四、违反后果&quot;">​</a></h2><ul><li><strong>轻度</strong>：剧情对设定有轻微越界，退回重写</li><li><strong>中度</strong>：反复为某主角/某势力绑架设定，相关叙事降格为模拟，不列入正史</li><li><strong>重度</strong>：系统性绑架设定以制造掠夺式主角光环，按规则二十二、规则二十一连同处置</li></ul><h2 id="五、监督主体" tabindex="-1">五、监督主体 <a class="header-anchor" href="#五、监督主体" aria-label="Permalink to &quot;五、监督主体&quot;">​</a></h2><p>阿赖耶网络+多层监督的设定依赖审计为第一层；锚点监督委员会查人物自主保护为第二层；共生法院审理设定绑架案件为第三层；万族各族对&quot;自己的族史是否被剧情歪曲&quot;有直接申诉权为第四层。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li>反能级浪费：剧情绑架设定造成的反复返工，是创作级能级浪费</li><li>反掠夺：否定&quot;主角绑架世界观&quot;的掠夺式叙事，公理六下人人自带无限本源，谁也不值得绑架全世界</li><li>唐罗上限对比：唐罗式体系设定随主角需要而扭曲；衡元宙设定自主，剧情只是它自然长出的枝叶</li><li>万族全覆盖：每个种族的设定、每个配角的人格都受保护，不为主角让路</li><li>超多元全开放：世界观扩容时，新设定同样自主，不被旧剧情绑架</li></ul><p>剧情不得绑架设定，对&quot;英雄叙事&quot;是一个温柔的解绑。旧宇宙总把文明的希望押在某个主角身上，于是剧情为了让主角持续耀眼，不得不不断扭曲配角、扭曲反派、扭曲世界。天道规则二十三让配角、反派、路人都有自己的设定与自主性——一个反派可以按其逻辑失败，而不必突然降智；一个配角可以按其性格选择，而不必为主角让路。文明的故事从此不再是&quot;一个人的独角戏&quot;，而是万族在设定内各自生长的群像。</p><p>剧情不绑架设定，也给了修炼者个人更大的安心。在旧宇宙，一个配角随时可能因为主角需要而被写死、写黑、写变形；在衡元宙，每个生灵的命运由其自身设定与因果决定，不被外部剧情摆布。这种&quot;命运自主&quot;感，是万族对文明产生信任的深层原因——你不会突然被作者一笔抹掉，因为你本身就是你自己故事的作者。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>剧情不得绑架设定，是文明终极定型对&quot;创作伦理&quot;的立法。故事该怎么走，由法则说了算，不由&quot;想爽&quot;说了算。</p><p>说到底，本篇所述的规则二十三·剧情不得绑架设定并非孤例——始终指向锚点共生文明的共建方向。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0020-锚点结构与层级.html">0020-锚点结构与层级</a> · <a href="./0956_模块5-规则二十二-设定自洽高于剧情便利.html">956-规则二十二-设定自洽高于剧情便利</a> · <a href="./0955_模块5-规则二十一-永不吃书永不烂尾.html">955-规则二十一-永不吃书永不烂尾</a> · <a href="./0958_模块5-规则二十四-世界观可无限扩容.html">958-规则二十四-世界观可无限扩容</a></li></ul>',24)])])}const c=a(r,[["render",i]]);export{d as __pageData,c as default};
